const response = $input.first().json;
const content = response.content[0].text;
const pageData = $('Process Each Page').first().json;
let parsed;
try {
  const jsonStr = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(jsonStr);
} catch (e) {
  parsed = { page_number: pageData.page_number, complexity: 'COMPLEX', reasoning: 'Parse error, defaulting to complex', element_count: 0, has_charts: false, has_tables: false };
}
return [{ json: { page_number: pageData.page_number, total_pages: pageData.total_pages, pdf_base64: pageData.pdf_base64, retry_count: pageData.retry_count, complexity: parsed.complexity, scout_reasoning: parsed.reasoning, element_count: parsed.element_count || 0, has_charts: parsed.has_charts || false, has_tables: parsed.has_tables || false } }];

const response = $input.first().json;
const markdown = response.content[0].text;
const pageData = $('Complexity Router').first().json;
return [{ json: { page_number: pageData.page_number, total_pages: pageData.total_pages, complexity: pageData.complexity, conversion_path: 'complex_describer', markdown_output: markdown, pdf_base64: pageData.pdf_base64 } }];

const response = $input.first().json;
const markdown = response.content[0].text;
const pageData = $('Complexity Router').first().json;
return [{ json: { page_number: pageData.page_number, total_pages: pageData.total_pages, complexity: pageData.complexity, conversion_path: 'standard', markdown_output: markdown, pdf_base64: pageData.pdf_base64 } }];

const response = $input.first().json;
const content = response.content[0].text;
const conversionData = $('Merge Conversion Paths').first().json;
let verification;
try {
  const jsonStr = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  verification = JSON.parse(jsonStr);
} catch (e) {
  verification = { confidence: 'low', issues: 'Verification parse error', numerical_match: false, structure_correct: false, claims_captured: false, page_number_correct: true };
}
return [{ json: { page_number: conversionData.page_number, complexity: conversionData.complexity, conversion_path: conversionData.conversion_path, confidence: verification.confidence, verification_issues: verification.issues, numerical_match: verification.numerical_match, structure_correct: verification.structure_correct, claims_captured: verification.claims_captured, markdown_output: conversionData.markdown_output } }];

const items = $input.all();
const pages = items.map(item => item.json).sort((a, b) => a.page_number - b.page_number);
const total = pages.length;
const highConf = pages.filter(p => p.confidence === 'high').length;
const medConf = pages.filter(p => p.confidence === 'medium').length;
const lowConf = pages.filter(p => p.confidence === 'low').length;
let markdown = '---
project: Demo Document
date: ' + new Date().toISOString().split('T')[0] + '
total_pages: ' + total + '
conversion_quality:
  high_confidence: ' + (total > 0 ? Math.round(highConf/total*100) : 0) + '%
  medium_confidence: ' + (total > 0 ? Math.round(medConf/total*100) : 0) + '%
  low_confidence: ' + (total > 0 ? Math.round(lowConf/total*100) : 0) + '%
pages_by_complexity:
  simple_moderate: ' + pages.filter(p => p.conversion_path === 'standard').length + '
  complex: ' + pages.filter(p => p.conversion_path === 'complex_describer').length + '
---

# Document Intelligence Pipeline Output
';
for (const page of pages) { markdown += '
' + page.markdown_output + '

---
'; }
markdown += '
## Pipeline Quality Report

| Page | Complexity | Path | Confidence | Issues |
|------|-----------|------|------------|--------|
';
for (const page of pages) { markdown += '| ' + page.page_number + ' | ' + page.complexity + ' | ' + page.conversion_path + ' | ' + page.confidence + ' | ' + (page.verification_issues || 'none') + ' |
'; }
return [{ json: { assembled_markdown: markdown, quality_scorecard: { total_pages: total, high_confidence: highConf, medium_confidence: medConf, low_confidence: lowConf }, pages_processed: pages.map(p => ({ page: p.page_number, complexity: p.complexity, path: p.conversion_path, confidence: p.confidence })) } }];

const input = $input.all();
const data = input[0].json;
const markdown = data.assembled_markdown || '';
const scorecard = data.quality_scorecard || {};
const pages = data.pages_processed || [];

// Parse YAML frontmatter into clean summary
let yamlBlock = '';
const yamlMatch = markdown.match(/^---\n([\s\S]*?)\n---/);
if (yamlMatch) {
  const lines = yamlMatch[1].split('\n');
  yamlBlock = '═══════════════════════════════════════════\n';
  yamlBlock += '  DOCUMENT INTELLIGENCE PIPELINE REPORT\n';
  yamlBlock += '═══════════════════════════════════════════\n\n';
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    if (trimmed.match(/^\w/) && trimmed.includes(':')) {
      const [key, ...val] = trimmed.split(':');
      const value = val.join(':').trim();
      const label = key.trim()
        .replace(/_/g, ' ')
        .replace(/\b\w/g, c => c.toUpperCase());
      if (value) {
        yamlBlock += `  ${label}: ${value}\n`;
      } else {
        yamlBlock += `\n  ${label}:\n`;
      }
    } else if (trimmed.includes(':')) {
      const [key, ...val] = trimmed.split(':');
      const label = key.trim()
        .replace(/_/g, ' ')
        .replace(/\b\w/g, c => c.toUpperCase());
      yamlBlock += `    ${label}: ${val.join(':').trim()}\n`;
    }
  }
  yamlBlock += '\n═══════════════════════════════════════════\n';
}

// Extract body after frontmatter
let body = markdown.replace(/^---\n[\s\S]*?\n---\n*/, '');

// Clean up page markers for readability
body = body.replace(/\[page: (\d+)\]/g, '\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n  PAGE $1\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
body = body.replace(/\[confidence: (\w+)\]/g, '[Confidence: $1]');
body = body.replace(/\[complex_visual: (\w+)\]/g, '[Complex Visual: $1]');

// Clean up markdown formatting for plain text display
body = body.replace(/^### (.+)$/gm, '\n▸ $1');
body = body.replace(/^## (.+)$/gm, '\n■ $1');
body = body.replace(/^# (.+)$/gm, '\n████ $1 ████');
body = body.replace(/\*\*(.+?)\*\*/g, '$1');
body = body.replace(/\*(.+?)\*/g, '$1');
body = body.replace(/^---$/gm, '');

// Clean up table to be readable
body = body.replace(/\| Page .*\|/g, '\n  Page  | Complexity | Path              | Confidence | Issues');
body = body.replace(/\|---.*\|/g,    '  ------+------------+-------------------+------------+-------');
body = body.replace(/\| (\d)/g, '  $1    ');
body = body.replace(/\|/g, ' | ');

const output = yamlBlock + '\n' + body;

return [{
  json: {
    formatted_output: output,
    quality_summary: {
      total_pages: scorecard.total_pages || 0,
      high_confidence: scorecard.high_confidence || 0,
      medium_confidence: scorecard.medium_confidence || 0,
      low_confidence: scorecard.low_confidence || 0
    },
    pages_processed: pages
  }
}];
